func (source workloadAutoscalers) Autoscalers(context.Context) ([]insights.Autoscaler, error) {
	if source.reconciler == nil {
		return nil, nil
	}
	last := source.reconciler.Last()
	roles := make([]string, 0, len(last))
	for role := range last {
		roles = append(roles, role)
	}
	slices.Sort(roles)
	out := make([]insights.Autoscaler, 0, len(roles))
	for _, role := range roles {
		spec, owned := source.reconciler.Owns(role)
		if !owned || spec.Scaling == nil {
			continue
		}
		result := last[role]
		current := result.Target
		if current == 0 {
			current = result.Replicas
		}
		out = append(out, insights.Autoscaler{Name: role, Current: current, Max: spec.Replicas.Max})
	}
	return out, nil
}

func (source placementVolumes) Volumes(ctx context.Context) ([]insights.Volume, error) {
	if source.store == nil {
		return nil, nil
	}
	members, _, err := placedVolumeMembers(ctx, source.store, false)
	if err != nil {
		return nil, err
	}
	out := make([]insights.Volume, 0, len(members))
	for _, member := range members {
		since := time.Time{}
		if volumeAttachmentState(member) == "attaching" {
			since = member.AttachRequestedAt
			if since.IsZero() && member.Stage == placement.StageAwaitingAttach {
				// Observed attachments retain their persisted phase-entry time while waiting.
				since = member.UpdatedAt
			}
		}
		out = append(out, insights.Volume{ID: member.VolumeID, Host: member.HostNode,
			State: volumeAttachmentState(member), Detail: "placement: " + string(member.Stage), StateSince: since})
	}
	return out, nil
}

func volumeAttachmentState(member placement.MemberState) string {
	switch member.Stage {
	case placement.StagePreparedAttach, placement.StageAwaitingAttach:
		return "attaching"
	case placement.StagePreparedVolume:
		return "available"
	case placement.StageStorageHandled, placement.StageTerminated, placement.StageRemoved:
		return "unknown"
	}
	if member.HostNode != "" && member.AttachmentID != "" {
		return "attached"
	}
	return "unknown"
}

func placedVolumeMembers(ctx context.Context, store placement.Store, skipUnreadable bool) (out []placement.MemberState, skipped []error, err error) {
	intents, err := store.ListIntents(ctx)
	if err != nil {
		return nil, nil, err
	}
	seen := make(map[string]bool)
	for _, intent := range intents {
		members, err := store.ListMembers(ctx, intent.DatabaseID, intent.PartitionID)
		if err != nil {
			if !skipUnreadable {
				return nil, nil, err
			}
			skipped = append(skipped, fmt.Errorf("partition %s/%s: %w", intent.DatabaseID, intent.PartitionID, err))
			continue
		}
		for _, member := range members {
			if id := member.State.VolumeID; id != "" && member.State.Stage != placement.StageRemoved && !seen[id] {
				seen[id] = true
				out = append(out, member.State)
			}
		}
	}
	return out, skipped, nil
}

type volumeListStore struct {
	placement.Store
	intents []placement.Intent
	members map[string][]placement.VersionedMemberState
}

func (store volumeListStore) ListIntents(context.Context) ([]placement.Intent, error) {
	return store.intents, nil
}

func (store volumeListStore) ListMembers(_ context.Context, databaseID, partitionID string) ([]placement.VersionedMemberState, error) {
	if members, ok := store.members[databaseID+"/"+partitionID]; ok {
		return members, nil
	}
	return nil, errors.New("partition unreadable")
}

func (volumeListStore) ReadTerminalIntent(context.Context, string, string) (authority.LogEntry, error) {
	return authority.LogEntry{}, errors.New("unused")
}

func volumeStuck(inputs *Inputs) []Insight {
	var out []Insight
	limit := inputs.Thresholds.VolumeAttachStuck
	// Hosts whose seat already reports the stuck attachment: the volume
	// provider describes the same placement state, so it must not open a
	// second problem for it.
	reported := map[string]bool{}
	if view := placement(inputs); view != nil {
		for _, database := range view.Databases {
			for _, member := range database.Members {
				if member.Stage != "prepared-attach" && member.Stage != "awaiting-attach" || member.UpdatedAt.IsZero() {
					continue
				}
				stuck := inputs.Now.Sub(member.UpdatedAt)
				if stuck < limit {
					continue
				}
				seat := database.DatabaseID + "/" + database.PartitionID + "/" + member.SeatID
				if member.HostNode != "" {
					reported[member.HostNode] = true
				}
				out = append(out, Insight{inputs: placementInputs, Severity: SeverityWarning, Score: stuck.Seconds(),
					Key:   "volume_stuck:seat:" + seat,
					Title: "Volume stuck attaching for seat " + member.SeatID,
					Why: fmt.Sprintf("Seat %s has waited in %s for %s; its retained volume is not attached.",
						member.SeatID, member.Stage, roundDuration(stuck)),
					Entity: Entity{Kind: "seat", ID: seat, Href: partitionHref(database.DatabaseID, database.PartitionID)},
					Evidence: []Evidence{{Label: "Waiting", Value: stuck.Seconds(), Unit: "s", Comparison: "<",
						Threshold: threshold(limit.Seconds())}},
					Actions: []Action{{Label: "Inspect the attachment",
						Command: "oci compute volume-attachment list --instance-id <host OCID>"},
						{Label: "Open storage", Href: "/storage"}}})
			}
		}
	}
	for _, volume := range inputs.Volumes {
		if !strings.Contains(strings.ToLower(volume.State), "attaching") || volume.StateSince.IsZero() ||
			volume.Host != "" && reported[volume.Host] {
			continue
		}
		stuck := inputs.Now.Sub(volume.StateSince)
		if stuck < limit {
			continue
		}
		out = append(out, Insight{inputs: []string{"volumes"}, Severity: SeverityWarning, Score: stuck.Seconds(),
			Title:  "Volume " + shortID(volume.ID) + " stuck attaching",
			Why:    fmt.Sprintf("Volume %s has been %s for %s.", volume.ID, volume.State, roundDuration(stuck)),
			Entity: Entity{Kind: "volume", ID: volume.ID, Href: volumeHref(volume.ID)},
			Evidence: []Evidence{{Label: "Attaching for", Value: stuck.Seconds(), Unit: "s", Comparison: "<",
				Threshold: threshold(limit.Seconds())}},
			Actions: []Action{{Label: "Open storage", Href: "/storage"}}})
	}
	return out
}

func startRuntimeObservability(ctx context.Context, cfg Config, role, member string) (*runtimeObservability, error) {
	settings := cfg.Observability
	if err := settings.Validate(); err != nil {
		return nil, err
	}
	runtime := &runtimeObservability{config: settings, cell: cfg.NATS.Cell, member: member, role: role,
		operationObservations: &operationObservationAPI{cell: cfg.NATS.Cell},
		registry:              observability.NewRegistry(true), health: new(observability.Health),
		events: observability.NewEventBus(observability.DefaultEventCapacity)}
	logger, err := observability.NewLogger(os.Stderr,
		observability.LogConfig{Format: settings.LogFormat, Level: settings.LogLevel}, runtime.events,
		observability.Identity(role, cfg.NATS.Cell)...)
	if err != nil {
		return nil, err
	}
	observability.ConfigureDefault(logger)
	runtime.registry.Register(observability.LogMetrics)
	runtime.health.Add(observability.Check{Name: "startup", Run: func(context.Context) (bool, string) {
		if runtime.started.Load() {
			return true, "runtime started"
		}
		return false, "runtime is still starting"
	}})
	if role == "controller" {
		runtime.usage = capacity.NewStore(cfg.NATS.Cell)
		runtime.startDecisionJournal(ctx)
	}
	server, err := observability.NewServer(settings, observability.ServerDeps{Registry: runtime.registry,
		Health: runtime.health, Events: runtime.events, LocalSessions: role == "host"})
	if err != nil {
		// An unusable bearer token file (missing, shared or malformed) fails
		// closed for the listener only: nothing is served, and the role
		// keeps running exactly as when the port cannot be bound.
		slog.WarnContext(ctx, "observability listener unusable; continuing without it",
			observability.ComponentKey, "observability", "error", err)
		return runtime, nil
	}
	runtime.mountUsage(server)
	runtime.operationObservations.mount(server)
	// A token-protected listener issues browser sessions; a tokenless
	// one is loopback only and refuses DNS names against rebinding.
	board := dashboard.New(dashboard.Options{Health: runtime.health, Events: runtime.events,
		SignOut: settings.BearerTokenFile != "", RequireLiteralHost: settings.BearerTokenFile == ""})
	board.Mount(server)
	serveErrors, err := server.Start(ctx, settings)
	if err != nil {
		slog.WarnContext(ctx, "observability listener unavailable; continuing without it",
			observability.ComponentKey, "observability", "address", settings.Address(), "error", err)
		return runtime, nil
	}
	go watchObservabilityListener(serveErrors)
	runtime.server = server
	runtime.addBoard(board, server)
	slog.InfoContext(ctx, "observability listener ready", observability.ComponentKey, "observability",
		"address", server.Addr().String())
	return runtime, nil
}

func (runtime *runtimeObservability) close() {
	if runtime == nil {
		return
	}
	if runtime.stopJournal != nil {
		runtime.stopJournal()
	}
	if runtime.server != nil {
		_ = runtime.server.Close()
	}
}

func SetDefault(recorder Recorder) (restore func()) {
	var holder *recorderHolder
	if recorder != nil {
		holder = &recorderHolder{recorder: recorder}
	}
	previous := defaultRecorder.Swap(holder)
	return func() { defaultRecorder.CompareAndSwap(holder, previous) }
}

// Default returns the installed recorder, or nil when records go to the log.
func Default() Recorder {
	if holder := defaultRecorder.Load(); holder != nil {
		return holder.recorder
	}
	return nil
}

func signTestAccessToken(t *testing.T, key *ecdsa.PrivateKey, kid string, claims map[string]any) string {
	t.Helper()
	encode := func(value any) string {
		data, err := json.Marshal(value)
		if err != nil {
			t.Fatal(err)
		}
		return base64.RawURLEncoding.EncodeToString(data)
	}
	signed := encode(map[string]string{"alg": "ES256", "typ": "at+jwt", "kid": kid}) + "." + encode(claims)
	digest := sha256.Sum256([]byte(signed))
	r, s, err := ecdsa.Sign(rand.Reader, key, digest[:])
	if err != nil {
		t.Fatal(err)
	}
	signature := make([]byte, 64)
	r.FillBytes(signature[:32])
	s.FillBytes(signature[32:])
	return signed + "." + base64.RawURLEncoding.EncodeToString(signature)
}

