				var server *machinesapi.Server
				embedded := cfg.NATS.Embedded
				server, err = machinesapi.NewServer(want.Config(embedded.Host, embedded.TLS.CertFile, embedded.TLS.KeyFile), apps, tenants, links)
				serveCtx, cancel := context.WithCancel(ctx)
				if err == nil {
					serving, err = server.Start(serveCtx)
				}
				if err != nil {
					cancel()
				} else {
					stop, running = cancel, want
					slog.InfoContext(serveCtx, "Machines API serving", "address", want.Config(embedded.Host, "", "").ListenAddress)
				}
			}
			if err != nil && err.Error() != failure {
				slog.WarnContext(ctx, "Machines API is not serving; retrying", "error", err)
			}
			failure = ""
			if err != nil {
				failure = err.Error()
			}
		}
		select {
		case <-ctx.Done():
			return nil
		case err := <-serving:
			slog.WarnContext(ctx, "Machines API stopped; restarting", "error", err)
			stop()
			running, serving = nil, nil
		case <-ticker.C:
		}
	}
}

func NewServer(config Config, apps *machines.Store, tenants *tenant.Store, links observability.ClusterSource) (*Server, error) {
	if err := config.Validate(); err != nil {
		return nil, err
	}
	if apps == nil || tenants == nil {
		return nil, errors.New("machines API requires the app and tenant stores")
	}
	s := &Server{config: config, apps: apps, tenants: tenants, mux: http.NewServeMux(), orgs: map[string]string{},
		links: links, linkCache: observability.Cache[observability.ClusterSnapshot]{TTL: 3 * time.Second},
		verifier: NewVerifier(config.Issuer, config.Audience, config.JWKSURLs)}
	for org, subjects := range config.Members {
		for _, subject := range subjects {
			s.orgs[subject] = org
		}
	}
	s.mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})
	s.mux.HandleFunc("GET /v1/openapi.json", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write(openAPI)
	})
	s.mux.HandleFunc("GET /v1/link-health", s.linkHealth)
	s.mux.Handle("GET /v1/apps", s.authorized(ScopeRead, s.listApps))
	s.mux.Handle("GET /v1/apps/{app}", s.authorized(ScopeRead, s.withApp(s.getApp)))
	s.mux.Handle("GET /v1/apps/{app}/machines", s.authorized(ScopeRead, s.withApp(s.listMachines)))
	s.mux.Handle("GET /v1/apps/{app}/machines/{id}", s.authorized(ScopeRead, s.withApp(s.getMachine)))
	return s, nil
}

// ServeHTTP lets tests and the controller exercise the routes directly.
func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	s.mux.ServeHTTP(w, r)
}

// Start binds the configured address and serves until ctx ends. The
// returned channel yields the terminal serve error.
func (s *Server) Start(ctx context.Context) (<-chan error, error) {
	var certificate tls.Certificate
	if s.config.TLSCertFile != "" {
		var err error
		if certificate, err = tls.LoadX509KeyPair(s.config.TLSCertFile, s.config.TLSKeyFile); err != nil {
			return nil, fmt.Errorf("load machines API TLS: %w", err)
		}
	}
	listener, err := (&net.ListenConfig{}).Listen(ctx, "tcp", s.config.ListenAddress)
	if err != nil {
		return nil, err
	}
	listener = netutil.LimitListener(listener, maxConnections)
	if s.config.TLSCertFile != "" {
		listener = tls.NewListener(listener, &tls.Config{MinVersion: tls.VersionTLS12, Certificates: []tls.Certificate{certificate}})
	}
	// No WriteTimeout: log streams (a later slice) are long-lived.
	s.http = &http.Server{Handler: observability.TraceHTTP(s), ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 30 * time.Second,
		IdleTimeout: 2 * time.Minute, MaxHeaderBytes: 16 << 10}
	result := make(chan error, 1)
	go func() {
		err := s.http.Serve(listener)
		if errors.Is(err, http.ErrServerClosed) {
			err = nil
		}
		result <- err
	}()
	context.AfterFunc(ctx, func() { _ = s.http.Close() })
	return result, nil
}

func (s *Server) authorized(scope string, next func(http.ResponseWriter, *http.Request, caller)) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		scheme, token, _ := strings.Cut(r.Header.Get("Authorization"), " ")
		if !strings.EqualFold(scheme, "Bearer") || token == "" {
			w.Header().Set("WWW-Authenticate", `Bearer realm="ts-orch"`)
			writeError(w, http.StatusUnauthorized, "unauthenticated", "a ts-auth bearer access token is required")
			return
		}
		principal, err := s.verifier.Verify(r.Context(), token)
		if err == nil && !slices.Contains(s.config.Clients, principal.ClientID) {
			err = fmt.Errorf("%w: client %q may not call this API", ErrUnauthenticated, principal.ClientID)
		}
		if err != nil {
			// Debug: the internet can send any number of bad tokens.
			slog.DebugContext(r.Context(), "machines API token rejected", observability.ComponentKey, "machinesapi", "error", err)
			w.Header().Set("WWW-Authenticate", `Bearer realm="ts-orch", error="invalid_token"`)
			writeError(w, http.StatusUnauthorized, "unauthenticated", "the access token was rejected")
			return
		}
		if !principal.HasScope(scope) {
			w.Header().Set("WWW-Authenticate", fmt.Sprintf(`Bearer realm="ts-orch", error="insufficient_scope", scope=%q`, scope))
			writeError(w, http.StatusForbidden, "insufficient_scope", "the token lacks scope "+scope)
			return
		}
		org, member := s.orgs[principal.Subject]
		if !member {
			writeError(w, http.StatusForbidden, "no_organization", "the caller is not a member of any organization")
			return
		}
		next(w, r, caller{Principal: principal, Org: org})
	})
}

func (s *Server) listApps(w http.ResponseWriter, r *http.Request, c caller) {
	apps, err := s.apps.Apps(r.Context())
	if err != nil {
		s.unavailable(w, err)
		return
	}
	owners := map[string]string{}
	visible := []machines.App{}
	for _, app := range apps {
		ok, err := s.visible(r.Context(), c, app, owners)
		if err != nil {
			s.unavailable(w, err)
			return
		}
		if ok {
			visible = append(visible, app)
		}
	}
	writeJSON(w, http.StatusOK, map[string][]machines.App{"apps": visible})
}

func (v *Verifier) Verify(ctx context.Context, token string) (Principal, error) {
	principal, err := v.verify(ctx, token)
	if err != nil {
		return Principal{}, fmt.Errorf("%w: %w", ErrUnauthenticated, err)
	}
	return principal, nil
}

func (v *Verifier) verify(ctx context.Context, token string) (Principal, error) {
	if len(token) > maxTokenBytes {
		return Principal{}, errors.New("token too large")
	}
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return Principal{}, errors.New("token is not a compact JWS")
	}
	var header jwtHeader
	if err := decodeSegment(parts[0], &header); err != nil {
		return Principal{}, fmt.Errorf("header: %w", err)
	}
	// RFC 9068 section 4: only a token typed as an access token, so an ID
	// token of the same issuer (typ JWT) is never accepted. ts-auth signs
	// with ES256 alone; no other algorithm, none included, is tried.
	if typ := strings.ToLower(header.Typ); typ != "at+jwt" && typ != "application/at+jwt" {
		return Principal{}, fmt.Errorf("typ %q is not at+jwt", header.Typ)
	}
	if header.Alg != "ES256" {
		return Principal{}, fmt.Errorf("alg %q is not ES256", header.Alg)
	}
	if header.Kid == "" {
		return Principal{}, errors.New("header has no kid")
	}
	key, err := v.key(ctx, header.Kid)
	if err != nil {
		return Principal{}, err
	}
	signature, err := base64.RawURLEncoding.DecodeString(parts[2])
	if err != nil || len(signature) != 64 {
		return Principal{}, errors.New("signature is not a base64url ES256 signature")
	}
	digest := sha256.Sum256([]byte(parts[0] + "." + parts[1]))
	if !ecdsa.Verify(key, digest[:], new(big.Int).SetBytes(signature[:32]), new(big.Int).SetBytes(signature[32:])) {
		return Principal{}, fmt.Errorf("signature does not verify with key %q", header.Kid)
	}
	var claims jwtClaims
	if err := decodeSegment(parts[1], &claims); err != nil {
		return Principal{}, fmt.Errorf("claims: %w", err)
	}
	now := v.now()
	switch {
	case claims.Issuer != v.issuer:
		return Principal{}, fmt.Errorf("issuer %q is not trusted", claims.Issuer)
	case !slices.Contains(claims.Audience, v.audience):
		return Principal{}, errors.New("token is not for this audience")
	case claims.Expiry == nil || !now.Before(time.Unix(*claims.Expiry, 0).Add(clockSkew)):
		return Principal{}, errors.New("token expired or has no exp")
	case claims.NotBefore != nil && now.Add(clockSkew).Before(time.Unix(*claims.NotBefore, 0)):
		return Principal{}, errors.New("token is not valid yet")
	case claims.IssuedAt != nil && now.Add(clockSkew).Before(time.Unix(*claims.IssuedAt, 0)):
		return Principal{}, errors.New("token was issued in the future")
	case !entityid.Valid(claims.Subject) || !entityid.Valid(claims.ClientID):
		return Principal{}, errors.New("token subject and client ID must be canonical ULIDs")
	}
	return Principal{Subject: claims.Subject, ClientID: claims.ClientID, Scopes: strings.Fields(claims.Scope)}, nil
}

func (v *Verifier) key(ctx context.Context, kid string) (*ecdsa.PublicKey, error) {
	key, age := v.cached(kid)
	if key != nil && age <= keysFresh {
		return key, nil
	}
	if key == nil {
		v.fetching.Lock()
	} else if !v.fetching.TryLock() {
		return usable(key, age, kid)
	}
	defer v.fetching.Unlock()
	key, age = v.cached(kid)
	v.mu.Lock()
	now := v.now()
	due := now.Sub(v.attempted) >= refreshEvery && (key == nil || age > keysFresh)
	if due {
		v.attempted = now
	}
	v.mu.Unlock()
	if due {
		keys, err := v.fetch(ctx, kid)
		switch {
		case err == nil:
			v.mu.Lock()
			v.keys, v.fetched = keys, now
			v.mu.Unlock()
			key, age = keys[kid], 0
		case key == nil:
			return nil, fmt.Errorf("fetch signing keys: %w", err)
		}
	}
	return usable(key, age, kid)
}

func (v *Verifier) fetch(ctx context.Context, kid string) (map[string]*ecdsa.PublicKey, error) {
	var first map[string]*ecdsa.PublicKey
	var errs []error
	for _, url := range v.jwksURLs {
		keys, err := v.fetchURL(ctx, url)
		if err != nil {
			errs = append(errs, fmt.Errorf("%s: %w", url, err))
			continue
		}
		if keys[kid] != nil {
			return keys, nil
		}
		if first == nil {
			first = keys
		}
	}
	if first != nil {
		return first, nil
	}
	return nil, errors.Join(errs...)
}

func (v *Verifier) fetchURL(ctx context.Context, url string) (map[string]*ecdsa.PublicKey, error) {
	// The fetch outlives the request that triggered it: a client that hangs
	// up must not cancel it and use up the refresh slot for everyone else.
	ctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), fetchTimeout)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, err
	}
	request.Header.Set("Accept", "application/json")
	response, err := v.client.Do(request)
	if err != nil {
		return nil, err
	}
	defer response.Body.Close()
	if response.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("key set returned %s", response.Status)
	}
	data, err := io.ReadAll(io.LimitReader(response.Body, maxJWKSBytes+1))
	if err != nil {
		return nil, err
	}
	if len(data) > maxJWKSBytes {
		return nil, errors.New("key set is too large")
	}
	var set struct {
		Keys []jwk `json:"keys"`
	}
	if err := json.Unmarshal(data, &set); err != nil {
		return nil, fmt.Errorf("decode key set: %w", err)
	}
	keys := map[string]*ecdsa.PublicKey{}
	for _, key := range set.Keys {
		// A key this verifier cannot use is skipped, not fatal: the set may
		// publish more than ES256 signing keys.
		if key.Kty != "EC" || key.Crv != "P-256" || key.Kid == "" || key.Use != "" && key.Use != "sig" ||
			key.Alg != "" && key.Alg != "ES256" {
			continue
		}
		x, errX := base64.RawURLEncoding.DecodeString(key.X)
		y, errY := base64.RawURLEncoding.DecodeString(key.Y)
		if errX != nil || errY != nil || len(x) != 32 || len(y) != 32 {
			continue
		}
		public, err := ecdsa.ParseUncompressedPublicKey(elliptic.P256(), append(append([]byte{4}, x...), y...))
		if err != nil {
			continue
		}
		keys[key.Kid] = public
	}
	if len(keys) == 0 {
		return nil, errors.New("key set has no usable ES256 key")
	}
	return keys, nil
}

func OpenStore(ctx context.Context, js jetstream.JetStream, region string, replicas int, fencer authority.Fencer) (*Store, error) {
	if js == nil || fencer == nil || !validRegion(region) || replicas != 1 && replicas != 3 && replicas != 5 {
		return nil, fmt.Errorf("%w: store configuration", ErrInvalid)
	}
	open := func(bucket, description string) (jetstream.KeyValue, error) {
		kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
			Bucket: bucket, Description: description, History: 4, MaxValueSize: maxRecordBytes,
			MaxBytes: BucketMaxBytes, Storage: jetstream.FileStorage, Replicas: replicas,
		})
		if err != nil {
			return nil, fmt.Errorf("open %s: %w", bucket, err)
		}
		return kv, nil
	}
	apps, err := open(Bucket, "ts-orch apps and machines")
	if err != nil {
		return nil, err
	}
	machines, err := open(MachineBucket, "ts-orch machines")
	if err != nil {
		return nil, err
	}
	statuses, err := open(StatusBucket, "ts-orch observed machine states")
	if err != nil {
		return nil, err
	}
	if _, err := list[App](ctx, apps, ">"); err != nil {
		return nil, fmt.Errorf("app inventory requires current-format state: %w", err)
	}
	inventory, err := list[Machine](ctx, machines, "*")
	if err != nil {
		return nil, err
	}
	for _, machine := range inventory {
		entry, err := machines.Get(ctx, machine.App+"."+machine.ID)
		if err != nil {
			return nil, fmt.Errorf("machine %s has no readable app index: %w", machine.ID, err)
		}
		if string(entry.Value()) != machine.ID {
			return nil, fmt.Errorf("%w: machine %s app index", ErrInvalid, machine.ID)
		}
	}
	return &Store{apps: apps, machines: machines, statuses: statuses, region: region, fencer: fencer}, nil
}

func (s *Store) Apps(ctx context.Context) ([]App, error) {
	apps, err := list[App](ctx, s.apps, "*")
	slices.SortFunc(apps, func(a, b App) int { return cmp.Compare(a.Name, b.Name) })
	return apps, err
}

func list[T any, P record[T]](ctx context.Context, kv jetstream.KeyValue, filter string) ([]T, error) {
	watcher, err := kv.WatchFiltered(ctx, []string{filter}, jetstream.IgnoreDeletes())
	if err != nil {
		return nil, fmt.Errorf("list %s: %w", filter, err)
	}
	defer stopWatch(watcher)
	var values []T
	var bad error
	for {
		select {
		case entry, ok := <-watcher.Updates():
			if !ok {
				return nil, fmt.Errorf("list %s: watcher closed early", filter)
			}
			if entry == nil {
				if bad != nil {
					return nil, bad
				}
				return values, nil
			}
			// Keep reading after a bad record: the watcher blocks on unread
			// values.
			if value, err := decode[T, P](entry.Key(), entry.Value(), entry.Revision()); err != nil {
				bad = errors.Join(bad, err)
			} else {
				values = append(values, value)
			}
		case <-ctx.Done():
			return nil, fmt.Errorf("list %s: %w", filter, ctx.Err())
		}
	}
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

func (m managedControllerConfig) placementConfig(cell string, onError func(error), onHold func(string)) placement.Config {
	settings := m.placement
	return placement.Config{
		Cell: cell, Region: m.region.Region, FaultDomains: m.region.FaultDomains,
		ManagedOwner: m.region.Owner, FleetGeneration: m.region.Generation,
		ImageID:     m.region.ImageID,
		Environment: settings.Environment, MemberRole: settings.MemberRole, Resources: settings.Resources,
		OnError: onError, OnHold: onHold,
	}
}

func loadManagedControllerConfig(cfg Config) (*managedControllerConfig, error) {
	controller := cfg.Controller
	configured := controller.OciRegionIntentFile != "" || controller.OciRegionConfig != "" || controller.PlacementConfig != ""
	if !configured {
		return nil, nil
	}
	if controller.OciRegionIntentFile == "" || controller.OciRegionConfig == "" || controller.PlacementConfig == "" {
		return nil, errors.New("managed controller requires OCI region intent, fleet config, and placement config together")
	}
	intent, region, settings, err := loadSignedManagedControllerConfig(cfg)
	if err != nil {
		return nil, err
	}
	managed := &managedControllerConfig{intent: intent, region: region, placement: settings}
	if err := managed.validateWorkloads(controller.Workloads); err != nil {
		return nil, err
	}
	return managed, nil
}

func (m managedControllerConfig) validateWorkloads(workloads map[string]WorkloadProfile) error {
	if _, exists := workloads[m.placement.MemberRole]; exists {
		return fmt.Errorf("placement member role %q overlaps a generic delivery workload profile", m.placement.MemberRole)
	}
	return nil
}

func parseManagedPlacementSettings(data []byte) (managedPlacementSettings, error) {
	var settings managedPlacementSettings
	if err := json.Unmarshal(data, &settings, json.RejectUnknownMembers(true)); err != nil {
		return managedPlacementSettings{}, fmt.Errorf("parse TerraBase placement config: %w", err)
	}
	return settings, nil
}

func loadSignedManagedControllerConfig(cfg Config) (oci.RegionIntent, oci.RegionConfig, managedPlacementSettings, error) {
	accepted, err := bootstrapstart.NewMarkerStore().ReadIdentity()
	if err != nil {
		return oci.RegionIntent{}, oci.RegionConfig{}, managedPlacementSettings{}, err
	}
	if err := bootstrapstart.CheckIdentityRekeyPrestart(accepted); err != nil {
		return oci.RegionIntent{}, oci.RegionConfig{}, managedPlacementSettings{}, err
	}
	inputs, err := bootstrapstart.LoadTrustInputs(accepted)
	if err != nil {
		return oci.RegionIntent{}, oci.RegionConfig{}, managedPlacementSettings{}, err
	}
	uid, gid, err := controllerServiceIdentity()
	if err != nil {
		return oci.RegionIntent{}, oci.RegionConfig{}, managedPlacementSettings{}, err
	}
	material, err := bootstrapstart.NewMaterialStore(nil, uid, gid)
	if err != nil {
		return oci.RegionIntent{}, oci.RegionConfig{}, managedPlacementSettings{}, err
	}
	want, err := material.ControllerConfigSHA256(accepted, inputs.Roots.Historical)
	if err != nil {
		return oci.RegionIntent{}, oci.RegionConfig{}, managedPlacementSettings{}, err
	}
	configWire, err := cfg.signedWire()
	if err != nil || controllerSHA256(configWire) != want {
		return oci.RegionIntent{}, oci.RegionConfig{}, managedPlacementSettings{}, errors.New("loaded controller config differs from accepted installation")
	}
	files := make([]bootstrap.ControllerConfigFile, len(bootstrap.ControllerConfigFileNames))
	for index, name := range bootstrap.ControllerConfigFileNames {
		wire, err := readInstalledControllerFile(controllerConfigDirectory, name, 0, 0, 0o444, bootstrap.MaxControllerSidecarBytes)
		if err != nil {
			return oci.RegionIntent{}, oci.RegionConfig{}, managedPlacementSettings{}, fmt.Errorf("read installed sidecar %s: %w", name, err)
		}
		if controllerSHA256(wire) != accepted.ConfigSHA256[name] {
			return oci.RegionIntent{}, oci.RegionConfig{}, managedPlacementSettings{}, fmt.Errorf("installed sidecar %s differs from accepted identity", name)
		}
		files[index] = bootstrap.ControllerConfigFile{Name: name, Bytes: wire, SHA256: accepted.ConfigSHA256[name]}
	}
	if _, err := ValidateAcceptedControllerConfig(accepted, configWire, want, files); err != nil {
		return oci.RegionIntent{}, oci.RegionConfig{}, managedPlacementSettings{}, err
	}
	intent, err := oci.ParseRegionIntent(files[0].Bytes)
	if err != nil {
		return oci.RegionIntent{}, oci.RegionConfig{}, managedPlacementSettings{}, err
	}
	region, err := oci.ParseRegionConfig(files[1].Bytes)
	if err != nil || region.Validate(intent) != nil {
		return oci.RegionIntent{}, oci.RegionConfig{}, managedPlacementSettings{}, errors.New("signed OCI region config is invalid")
	}
	settings, err := parseManagedPlacementSettings(files[2].Bytes)
	return intent, region, settings, err
}

func StartController(ctx context.Context, config Config, store Store, fencer authority.Fencer, fleet oci.Fleet, hosts HostView, desired DesiredWriter, resolveArtifact ArtifactResolver) (*Controller, error) {
	if ctx == nil || ctx.Err() != nil {
		return nil, errors.New("placement controller requires a live context")
	}
	if err := config.validate(); err != nil {
		return nil, err
	}
	if store == nil || fencer == nil || fleet == nil || hosts == nil || desired == nil || resolveArtifact == nil {
		return nil, errors.New("placement controller requires durable state, authority, OCI fleet, host view, desired writer and artifact admission")
	}
	if fleet.Region() != config.Region {
		return nil, errors.New("placement controller region differs from its pinned OCI fleet")
	}
	if config.TickInterval == 0 {
		config.TickInterval = defaultTickInterval
	}
	return &Controller{config: config, store: store, fencer: fencer, fleet: fleet, hosts: hosts, desired: desired, resolveArtifact: resolveArtifact}, nil
}

func (config Config) validate() error {
	if !validToken(config.Cell) || !knownRegion(config.Region) || !validToken(config.ManagedOwner) ||
		!validToken(config.Environment) || !validToken(config.MemberRole) || config.FleetGeneration == 0 ||
		!strings.HasPrefix(config.ImageID, "ocid1.image.") || len(config.ImageID) > 255 || strings.ContainsAny(config.ImageID, " \t\r\n") ||
		!positive(config.Resources) ||
		config.Resources.CPU > 4096 || config.Resources.MemoryBytes > 1<<50 || config.Resources.DiskBytes > 1<<50 {
		return errors.New("placement controller config has an invalid cell, region, owner, role, or resource profile")
	}
	if err := config.VolumeDeadlines.Validate(); err != nil {
		return err
	}
	if config.LostMemberGrace < 0 || config.LostMemberGrace > 7*24*time.Hour {
		return errors.New("placement lost member grace must be between zero and seven days")
	}
	if config.TickInterval < 0 || config.TickInterval != 0 && (config.TickInterval < minTickInterval || config.TickInterval > maxTickInterval) {
		return errors.New("placement tick interval must be zero or between 100ms and 5m")
	}
	if len(config.FaultDomains) < 2 || len(config.FaultDomains) > 3 || config.FaultDomains[0] == config.FaultDomains[1] {
		return errors.New("placement region requires at least two distinct OCI fault domains")
	}
	for _, domain := range config.FaultDomains {
		if len(domain) != len("FAULT-DOMAIN-1") || !strings.HasPrefix(domain, "FAULT-DOMAIN-") || domain[len(domain)-1] < '1' || domain[len(domain)-1] > '3' {
			return fmt.Errorf("invalid configured OCI fault domain %q", domain)
		}
	}
	return nil
}

