			SystemCredentialsFile: path("system.creds"), TicketPublicKeyFile: path("ticket.pub")}},
		Controller: ControllerConfig{CandidateID: entityid.Derive("controller", accepted.DeploymentID, accepted.Cell, accepted.Slot),
			ResponseKeyFile: path("controller-a-response.key"), BrokerTicketKeyFile: path("ticket.key"), HostNATSIssuerSeedFile: path("host-nats-issuer.seed"),
			HostTLSIssuerKeyFile: path("host-tls-issuer-key.pem"), HostTLSIssuerCertFile: path("host-tls-issuer-cert.pem"), HostEnrollmentListenAddress: "10.251.0.11:8443",
			OciRegionIntentFile: controllerSidecarPath("oci-region-intent.json"), OciRegionConfig: controllerSidecarPath("oci-region.json"), PlacementConfig: controllerSidecarPath("placement.json"),
			TrustedSigners: []TrustedSignerConfig{{Actor: "operator", PublicKey: base64.StdEncoding.EncodeToString(publicSigner), Roles: []string{"terrabase"}, Environments: []string{"canary"}}}}}
	intent := oci.RegionIntent{SchemaVersion: 1, Generation: 7, BootstrapRegion: oci.RegionGRU, Regions: []oci.RegionMapping{{Cell: oci.RegionGRU, OCIRegion: "sa-saopaulo-1"}}}
	region := oci.RegionConfig{Region: oci.RegionGRU, Generation: 7, Endpoint: "https://iaas.sa-saopaulo-1.oraclecloud.com", CompartmentID: "ocid1.compartment.oc1..owned",
		ImageCompartmentID: "ocid1.compartment.oc1..image", AvailabilityDomain: "AD-1", FaultDomains: []string{"FAULT-DOMAIN-1"}, SubnetID: "ocid1.subnet.oc1..owned",
		NetworkSecurityGroupIDs: []string{"ocid1.networksecuritygroup.oc1..owned"},
		BootVolumeGB:            50, BootVolumeVPUsPerGB: 10, DataVolumeVPUsPerGB: 10, MaxDataVolumeGB: 50, ImageID: accepted.ImageOCID, Shape: "VM.Standard.Future.Flex", Owner: "regional-owner"}
	files := map[string][]byte{"controller.json": encode(config), "oci-region-intent.json": encode(intent), "oci-region.json": encode(region),
		"placement.json": encode(managedPlacementSettings{Environment: accepted.Environment, MemberRole: "terrabase"})}
	accepted.ConfigSHA256 = map[string]string{}
	for name, wire := range files {
		accepted.ConfigSHA256[name] = controllerSHA256(wire)
	}
	accepted.LaunchMaterialSHA256 = map[string]string{}
	for _, name := range identityRekeyLaunchFiles {
		files[name] = []byte(name)
		accepted.LaunchMaterialSHA256[name] = controllerSHA256(files[name])
	}
	if err := accepted.Validate(); err != nil {
		t.Fatal(err)
	}
	return accepted, files, config
}

func newRolloutControl(cfg Config, services *specRegistry, region string) (*rolloutControl, error) {
	c := &rolloutControl{cell: cfg.NATS.Cell, spool: rolloutexec.DefaultSpoolDir, architectures: []string{goruntime.GOARCH},
		layout: selfupdate.NewLayout(selfupdate.DefaultRoot), ticks: make(chan struct{}, 1)}
	c.policy = rollout.DefaultPolicy
	if services != nil {
		c.controllerNode = func(slot string) string { return services.controllerNode(cfg.NATS.Cell, slot) }
	}
	if region != "" {
		c.channel = instancePrincipalChannel(region, strings.ToUpper(cfg.NATS.Cell))
	}
	if services != nil && services.roots != nil {
		c.roots, c.environment = services.roots, services.identity.Environment
		// Every controller slot shares the admitted image; OCI observes the managed host processor.
		if services.ociRegion != nil {
			managed := *services.ociRegion
			c.managedArchitecture = func(ctx context.Context) (string, error) {
				return managedImageArchitecture(ctx, managed)
			}
		}
		// The leader refuses a receipt that no node would stage; every node
		// still verifies it against its own roots before it keeps a byte.
		// The current roots are read per receipt, so a root rotation applies.
		c.verify = func(receipt, delegation []byte, now time.Time) (rollout.Release, error) {
			policy := selfupdate.ReceiptPolicy{Roots: services.roots.current(), Environment: services.identity.Environment,
				Cell: strings.ToUpper(cfg.NATS.Cell), Architecture: goruntime.GOARCH}
			verified, err := policy.Verify(receipt, delegation, now)
			if err != nil {
				return rollout.Release{}, err
			}
			envelope, err := trust.DecodeEnvelope(receipt)
			if err != nil {
				return rollout.Release{}, err
			}
			admitted := rollout.Release{Digest: verified.Receipt().SHA256,
				SourceRevision: verified.Receipt().SourceRevision, Receipt: receipt, Delegation: delegation, CreatedAt: envelope.IssuedAt}
			// An update receipt's authentic payload names the CI run.
			if envelope.Scope.Domain == release.UpdateReceiptDomain {
				var update release.BinaryUpdateReceipt
				if err := protocol.DecodeStrict(envelope.Payload, &update, trust.MaxPayloadBytes); err != nil {
					return rollout.Release{}, err
				}
				admitted.RunNumber = update.Lineage.QualificationRunNum
				admitted.ReleaseSequence = update.ReleaseSequence
				admitted.SequenceMigrationSHA256 = update.SequenceMigrationSHA256
			}
			return admitted, nil
		}
	}
	return c, nil
}

func newReleaseSigner(t *testing.T) releaseSigner {
	t.Helper()
	now := time.Now().UTC().Truncate(time.Second)
	rootPublic, rootPrivate, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	leafPublic, leafPrivate, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	roots, err := trust.ParseKeyring(rootPublic)
	if err != nil {
		t.Fatal(err)
	}
	keyID, err := trust.KeyID(leafPublic)
	if err != nil {
		t.Fatal(err)
	}
	encoded, err := trust.EncodeDelegatedPublicKey(leafPublic)
	if err != nil {
		t.Fatal(err)
	}
	delegation, err := release.SignUpdateDelegation(release.BinaryUpdateDelegation{
		Schema: release.UpdateDelegationSchema, SubjectKeyID: keyID, SubjectPublicKey: encoded,
		Environment: "production", Architectures: []string{"amd64", "arm64"},
		Repository: release.QualificationRepository, Workflow: release.QualificationWorkflow,
		Ref: release.LineageRef, LineageBase: strings.Repeat("9", 40),
	}, now.Add(-time.Minute), now.Add(7*24*time.Hour), rootPrivate)
	if err != nil {
		t.Fatal(err)
	}
	return releaseSigner{roots: roots, delegation: delegation, root: rootPrivate, leaf: leafPrivate, now: now}
}

